"use client";

import { useState } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import {
  LayoutDashboard,
  MapPin,
  Cpu,
  Navigation,
  BarChart3,
  LogOut,
  Menu,
  Zap,
  ChevronDown,
  Check,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { logout } from "@/lib/api/auth";
import { useAuth } from "@/context/AuthContext";

const navItems = [
  { icon: LayoutDashboard, label: "MAIN SCREEN", href: "/" },
  { icon: MapPin, label: "AREA", href: "/area" },
  { icon: Cpu, label: "SENSORS", href: "/sensors" },
  { icon: Navigation, label: "DRONES", href: "/drones" },
  { icon: BarChart3, label: "REPORT", href: "/report" },
  { icon: MapPin, label: "MAP", href: "/maps/manage" },
 ];

export function DashboardHeader() {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const router = useRouter();
  const pathname = usePathname();
  const { user, refreshUser } = useAuth();

  const isActive = (href: string) => {
    if (href === "/") {
      return pathname === "/";
    }
    return pathname.startsWith(href);
  };

  async function handleLogout() {
    await logout();
    await refreshUser();
    router.push("/login");
  }

  const activeItem = navItems.find((item) => isActive(item.href)) || navItems[0];
  const ActiveIcon = activeItem.icon;

  const userName = user?.name || "Operator";
  const userInitial = userName.charAt(0).toUpperCase();

  return (
    <header className="flex h-16 items-center justify-between border-b border-slate-800 bg-[#0f172a] px-4 md:px-6 shadow-md shadow-slate-950/40">
      {/* Brand Text Name */}
      <Link href="/" className="flex items-center gap-3 group py-1">
        <div className="flex items-center gap-2.5 py-1.5 px-3.5 rounded-xl bg-slate-800/90 border border-slate-700 shadow-sm shadow-slate-950/50 transition-all duration-200 group-hover:border-slate-600">
          <span className="text-xl md:text-2xl font-black tracking-widest text-white">
            DMS
          </span>
          <span className="hidden sm:inline-block text-xs font-semibold tracking-wider text-slate-400 border-l border-slate-700 pl-2.5">
            DRONE MANAGEMENT SYSTEM
          </span>
        </div>
      </Link>

      {/* Dropdown Navigation System (Desktop & Tablet) */}
      <nav className="hidden items-center md:flex">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="sm"
              className="gap-2.5 px-4 py-2 text-xs font-bold rounded-xl border border-slate-700 bg-slate-800 text-white shadow-sm hover:bg-slate-700 hover:text-white transition-all duration-150 focus:ring-2 focus:ring-blue-500/40"
            >
              <span className="text-slate-400 font-medium hidden lg:inline-block">Section:</span>
              <ActiveIcon className="h-4 w-4 text-blue-400" />
              <span className="tracking-wide text-sm">{activeItem.label}</span>
              <ChevronDown className="h-4 w-4 text-slate-400 ml-1" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent
            align="start"
            sideOffset={8}
            className="min-w-[220px] bg-[#0f172a] border border-slate-800 rounded-xl shadow-2xl shadow-black/60 p-1.5 font-medium z-[9999]"
          >
            <div className="px-3 py-2 text-[10px] font-extrabold uppercase tracking-wider text-slate-400 border-b border-slate-800/80 mb-1">
              Select Navigation
            </div>
            {navItems.map((item) => {
              const itemActive = isActive(item.href);
              const ItemIcon = item.icon;
              return (
                <DropdownMenuItem key={item.label} asChild>
                  <Link
                    href={item.href}
                    className={`flex items-center justify-between rounded-lg px-3 py-2 text-xs cursor-pointer transition-colors ${
                      itemActive
                        ? "bg-slate-800 text-white font-bold"
                        : "text-slate-300 hover:bg-slate-800/60 hover:text-white"
                    }`}
                  >
                    <div className="flex items-center gap-2.5">
                      <ItemIcon className={`h-4 w-4 ${itemActive ? "text-blue-400" : "text-slate-400"}`} />
                      <span>{item.label}</span>
                    </div>
                    {itemActive && <Check className="h-3.5 w-3.5 text-blue-400" />}
                  </Link>
                </DropdownMenuItem>
              );
            })}
          </DropdownMenuContent>
        </DropdownMenu>
      </nav>

      {/* User Info & Logout */}
      <div className="hidden items-center gap-4 md:flex">
        <div className="flex items-center gap-2 px-3 py-1 rounded-full bg-slate-800 border border-slate-700">
          <div className="h-6 w-6 rounded-full bg-slate-900 text-white font-bold flex items-center justify-center text-xs border border-slate-700">
            {userInitial}
          </div>
          <span className="text-xs font-semibold text-slate-200 max-w-[120px] truncate">
            {userName}
          </span>
        </div>

        <Button
          variant="ghost"
          size="sm"
          className="gap-2 text-xs text-slate-400 hover:bg-red-500/10 hover:text-red-400 hover:border-red-500/30 border border-transparent transition-all hover:cursor-pointer"
          onClick={handleLogout}
        >
          <LogOut className="h-4 w-4" />
          LOGOUT
        </Button>
      </div>

      {/* Mobile Menu Drawer */}
      <Sheet open={mobileMenuOpen} onOpenChange={setMobileMenuOpen}>
        <SheetTrigger asChild>
          <Button
            variant="ghost"
            size="icon"
            className="md:hidden text-white hover:bg-slate-800"
          >
            <Menu className="h-6 w-6" />
          </Button>
        </SheetTrigger>
        <SheetContent
          side="right"
          className="w-72 border-slate-800 bg-[#0f172a] p-0"
        >
          <div className="flex h-16 items-center justify-between border-b border-slate-800 px-4">
            <span className="text-lg font-bold text-white tracking-wide">Navigation</span>
          </div>
          <nav className="flex flex-col gap-2 p-4">
            {navItems.map((item) => (
              <Link key={item.label} href={item.href}>
                <Button
                  variant="ghost"
                  className={`w-full justify-start gap-3 rounded-lg ${
                    isActive(item.href)
                      ? "bg-slate-800 text-white border border-slate-700 font-semibold"
                      : "text-slate-400 hover:bg-slate-800/60 hover:text-white"
                  }`}
                  onClick={() => setMobileMenuOpen(false)}
                >
                  <item.icon className={`h-5 w-5 ${isActive(item.href) ? "text-blue-400" : "text-slate-400"}`} />
                  {item.label}
                </Button>
              </Link>
            ))}

            <div className="my-4 border-t border-slate-800" />

            <Button
              variant="ghost"
              className="justify-start gap-3 text-slate-400 hover:bg-red-500/10 hover:text-red-400"
              onClick={handleLogout}
            >
              <LogOut className="h-5 w-5" />
              LOGOUT
            </Button>
          </nav>
        </SheetContent>
      </Sheet>
    </header>
  );
}
